    sh.innerHTML = '<div class="pb-edu-sheet-inner"><div class="pb-edu-sheet-head"><h2 id="aiAskSheetTitle">' + escapeHtml(PB_AI_NAME) + '</h2><span class="pb-ask-head-acts"><button type="button" class="pb-btn small ghost" id="aiAskNewChat" onclick="pbAiAskNewChat()"' + (pbAiAskHistory.length ? '' : ' hidden') + '>New Chat</button><button type="button" class="pb-btn small" id="aiAskSheetClose" onclick="pbAskSheetClose()">Close</button></span></div><div id="aiAskSheetBody"></div></div>';
