  function pbAiParseTeacher(text, ex, q) {
    let lines = String(text || '').replace(/\r/g, '').split('\n');
    let type = '', sources = [];
    const ti = lines.findIndex(l => /^\s*TYPE:/i.test(l));
    if (ti !== -1) { type = (lines[ti].match(/TYPE:\s*(\w+)/i) || [])[1] || ''; lines.splice(ti, 1); }
    const si = lines.map(l => /^\s*SOURCES:/i.test(l)).lastIndexOf(true);
    if (si !== -1) { sources = (lines[si].match(/\d+/g) || []).map(Number); lines.splice(si, 1); }
    const body = lines.join('\n').replace(/\*\*/g, '').replace(/^#+\s*/gm, '').trim();
    const used = ex.filter(x => sources.includes(x.n) || new RegExp('\\[' + x.n + '\\]').test(body));
    const safety = /safety/i.test(type) || PB_AI_SAFETY_RX.test(q); // owner Nov 3: a word like "trench" in the answer alone no longer shows the safety banner (it showed on a schedule question)
    return { body, safety, sources: used };
  }
  // Questions the AI must never answer (independent review SF5): checked on the phone BEFORE anything is
