    const pv = pbPlansEl('planPrevBtn'), nx = pbPlansEl('planNextBtn'); if (pv) pv.disabled = pbPlanV.i === 0; if (nx) nx.disabled = pbPlanV.i >= pbPlanV.sheets.length - 1;
