      for (let p = 1; p <= pdf.numPages; p++) { const pg = await pdf.getPage(p); const v = pg.getViewport({ scale: 1 }); if (Math.max(v.width, v.height) >= 1150) sheetPages.push(p); try { pg.cleanup(); } catch (e) {} }
