    const numKey = v => { const t = String(v).trim(); return (t !== '' && isFinite(Number(t))) ? (t.startsWith('-') ? '-' : '') + String(Math.abs(Number(t))) : v; };
    const fields = Array.from(root.querySelectorAll('input, select, textarea')).filter(el => el.type !== 'file' && el.id !== 'duplicateRunSel' && !/^(seg\d+)?endSta$|StaTxt$/.test(el.id) && !(el.closest && el.closest('.pb-ai-review'))).map(el => (el.id || el.name || '') + '=' + (el.type === 'checkbox' || el.type === 'radio' ? el.checked : el.type === 'number' ? numKey(el.value) : el.value));
