      const why = [];
      if ((entry.fieldNotes || []).some(n => !n.pointId && !n.displaced && n.station === r.station)) why.push('holds a field note');
      if ((pbNoteDraftText.get(prefix + r.station) || '').trim()) why.push('note being written');
      if (w.drafts.some(ph => ph.owner === prefix + r.station) || capturing.includes(prefix + r.station)) why.push('photo not saved yet');
      if (w.pending.some(x => x.ctx && !x.ctx.pointId && !x.ctx.displaced && fmt(x.ctx.station, 1) === r.station)) why.push('photo waiting to retry');
