    runs.forEach(r => lines.push((multi ? 'Run ' + r.n + ': ' : '') + (r.cfg.on && r.cfg.len ? 'rows at ' + PB_LAY_DIV_WORDS[r.cfg.div] + ' of each ' + pbLayFt(r.cfg.len) + pbPiAWord(r.cfg.lenAuto) + ' stick (pipe laying length; stations calculated, not measured)' : 'rows every ' + (pbLayRunIv(entry, r) !== null ? pbLayRunIv(entry, r) : '\u2014') + ' ft (interval)')));
