    pbErrTags.length = 0; // UX batch 1: which field each message below is about
    if (elevOutOfRange(hi)) errors.push(pbErrAt('HI (' + hi + ') has more than 5 digits before the decimal \u2014 check the benchmark elevation and backsight, or the direct HI entry, for a typo.', pbHiField()));
    // A point in Invert Elevation mode with a reading typed in (but no elevation)
