        const segM = /^seg(\d+)(start|end)$/.exec(p);
        const where = getPointLabel(p, p === 'start' ? 'Start' : p === 'end' ? 'End' : segM ? 'Run ' + segM[1] + ' ' + (segM[2] === 'start' ? 'Start' : 'End') : 'A hub');
