      if (trenchWidth !== null && trenchWidth <= 0) segErrors.push(pbErrAt(cfg.notePrefix + 'Trench width must be greater than zero \u2014 check for a typo, or leave it blank if unknown.', pbSegFieldFor(cfg.startPrefix, 'TrenchWidth')));
