    let intervalStations = [];
    if (!pbLayCfg(1).on) for (let d = 0; d < seg1.totalDist; d += interval) intervalStations.push(Math.round(d*1000)/1000);
    intervalStations.push(Math.round(seg1.totalDist*1000)/1000);
