      const io = p => /\bIE\s*IN\b|\bINV?\.?\s+IN\b/i.test(p.label || '') ? 'in' : /\bIE\s*OUT\b|\bINV?\.?\s+OUT\b/i.test(p.label || '') ? 'out' : null;
