        const run = nums.every(n => n !== null) && nums.slice().sort((a, b) => a - b).every((n, i, a) => i === 0 || n === a[i - 1] + 1);
        const sorted = nums.slice().sort((a, b) => a - b);
        const who = run ? (reach.length === 1 ? 'Stake ' + sorted[0] : 'Stakes ' + sorted[0] + '\u2013' + sorted[sorted.length - 1])
          : nums.every(n => n !== null) ? 'Stakes ' + sorted.join(', ') : reach.map(p => p.label).join(', ');
