  // Renders the results table from an archive entry's own intervalRows — the single
  // source of truth after lock — so it can be re-run whenever a manual interval is
  // added, without losing already-saved field notes (matched back up by station).
  // Evidence added while a distance correction was pending that was then not
  // saved, at a station that cannot exist in the confirmed geometry. It is
  // kept OUT of intervalRows (so it never counts toward installed footage),
  // but must be visible everywhere the run is read.
  function pbUnplacedItems(entry) {
    return (entry.unplacedEvidence || []).map(u => {
      const r = u.row || {};
      const note = r.pointId ? (entry.fieldNotes || []).find(n => n.pointId === r.pointId) : null;
      const photos = [].concat(r.photos || [], (note && note.photos) ? note.photos : []);
      return { station: r.stationFt, label: r.label || '', reason: u.reason || '', time: u.time, noteText: note ? (note.text || '') : '', photos };
    });
  }
  function pbRenderUnplacedPanel(entry) {
    const el = document.getElementById('unplacedEvidencePanel');
    if (!el) return;
    const items = pbUnplacedItems(entry);
    if (!items.length) { el.style.display = 'none'; el.innerHTML = ''; return; }
    el.style.display = '';
    el.innerHTML = '<div class="pb-tag" style="margin:12px 16px 0 16px;">Unplaced Evidence (' + items.length + ') \u2014 not part of the installed run</div>'
      + '<div style="margin:0 16px 8px 16px; font-size:12px;">Excluded from installed footage and from the interval table; preserved here.</div>'
      + items.map(it => '<div class="pb-review-item" style="margin:0 16px 8px 16px;">'
        + '<div><strong>Station ' + (typeof it.station === 'number' ? it.station.toFixed(1) : '?') + ' ft' + (it.label ? ' (' + escapeHtml(it.label) + ')' : '') + '</strong> \u2014 recorded ' + escapeHtml(new Date(it.time).toLocaleString()) + '</div>'
        + '<div style="font-size:12px;">Why unplaced: ' + escapeHtml(it.reason) + '</div>'
        + (it.noteText ? '<div style="font-size:12px;">Note: ' + escapeHtml(it.noteText) + '</div>' : '')
        + (it.photos.length ? '<div>' + it.photos.map(u => '<img class="pb-zoomable" alt="Photo" src="' + pbSafePhotoUrl(u) + '" style="width:64px;height:64px;object-fit:cover;margin:4px 4px 0 0;">').join('') + '</div>' : '')
        + '</div>').join('');
  }
  // A tap-to-copy cell from a saved row's text. The value travels in a data
  // attribute (escaped), never inside the onclick's JS: an escaped quote there
  // is decoded back into a quote before the script runs.
  // UX-42: tapping offers Copy Number or Copy With Context (station, what the
  // value is, rod, run), chosen in pbChooseResultsCopy.
  function pbCopyCell(v, field, idx) { return `<td class="pb-tap-copy" role="button" tabindex="0" data-copy="${escapeHtml(v)}" data-field="${field || ''}" data-row="${idx === undefined ? '' : idx}" onclick="pbChooseResultsCopy(this)" onkeydown="pbCopyCellKey(event, this, pbChooseResultsCopy)">${escapeHtml(v)}</td>`; }
  // The run the Results panels below were last opened for. Their pickers, stop list and
  // typed text belong to that run: another run's (or account's) Results start closed.
  let pbResultsPanelsFor = null;
  function pbCloseResultsPanels() {
    ['correctDistancePanel', 'addIntervalPanel', 'endIncompletePanel', 'crewLogAddForm', 'correctDistanceError', 'addIntervalError'].forEach(id => { const el = document.getElementById(id); if (el) el.style.display = 'none'; });
    ['newIntervalStation', 'newIntervalLabel', 'correctDistanceReason', 'correctDistanceVal', 'correctHubStation', 'crewLogName'].forEach(id => { const el = document.getElementById(id); if (el) el.value = ''; });
    ['correctDistanceRunSel', 'endIncompleteStation', 'correctHubElevWrap'].forEach(id => { const el = document.getElementById(id); if (el) el.innerHTML = ''; });
  }
  // ================= batch 22 NOTES: delays, utility conflicts, rework and equipment, as quick entries in the run's notes =================
  // Owner (Oct 2026): items #4-#7 go "in the notes during a run". Each entry belongs to the run SESSION (entry.siteLog), as its
  // field notes do (a draft never holds them; Continue Today starts a new session with its own). Saved through the run's own
  // queue and rolled back if the save fails. Every save keeps the device time, its zone and the account; an edit keeps the
  // version it replaces in the entry's history (nothing is taken out). Owner ruling (review S1/S2): these are information, not
