  // [key, label on screen, short name in totals]
  const PB_SL_DELAY = [['utility', 'Utility conflict', 'utility conflict'], ['inspector', 'Waiting on inspector', 'inspector'], ['weather', 'Weather', 'weather'], ['equipment', 'Equipment down', 'equipment down'],
    ['material', 'Waiting on material', 'material'], ['survey', 'Waiting on survey / stakes', 'survey/stakes'], ['traffic', 'Traffic control', 'traffic control'], ['other', 'Other', 'other']];
  const PB_SL_WHAT = [['water', 'Water', 'water'], ['gas', 'Gas', 'gas'], ['electric', 'Electric', 'electric'], ['telecom', 'Telecom', 'telecom'], ['sewer', 'Sewer', 'sewer'], ['storm', 'Storm', 'storm'],
    ['abandoned', 'Abandoned line', 'abandoned'], ['unknown', 'Unknown', 'unknown']];
  const PB_SL_REWORK = [['grade', 'Grade off', 'grade off'], ['damaged', 'Damaged pipe', 'damaged pipe'], ['test', 'Failed test', 'failed test'], ['inspector', 'Inspector call', 'inspector call'], ['other', 'Other', 'other']];
  const pbSlOpt = (list, k) => list.find(x => x[0] === k) || [k, String(k || 'not given'), String(k || 'not given')];
  const pbSlNum = (v) => typeof v === 'number' && isFinite(v) && v > 0 ? v : 0;
  // hours as the crews say them: 2.5, 1.0, 0.25
  function pbSlH(v) { const n = Math.round((Number(v) || 0) * 100) / 100; return Math.abs(n * 10 - Math.round(n * 10)) < 1e-6 ? n.toFixed(1) : n.toFixed(2); }
