    const noteText = (f) => f ? 'Saved ' + new Date(f.enteredAt).toLocaleString() + (f.enteredBy ? ' by ' + f.enteredBy : '') : '';
    const priorForeman = entry.foreman ? pbClone(entry.foreman) : null;
