    if (dup) { pbConfirm(dup.name + ' is already on this run\u2019s log as ' + type + (dup.status === 'in' ? ' (checked in now)' : '') + '. Add a second row anyway? Each row counts its own hours.', () => pbAddCrewLogEntry(checkIn, true), 'Already on the Log', { no: 'Cancel', yes: 'Add Anyway' }); return; }
    const addKey = entry.id + '|' + name + '|' + type + '|' + category;
