    const inAt = p.status !== 'in' && typeof outAt === 'number' ? Math.min(now, Math.max(outAt, (p.log || []).reduce((t, l) => (l && typeof l.time === 'number' && l.time > t) ? l.time : t, 0))) : null; /* feat_foreman 18: a check-in time entered after the fact */
