    if (typeof g.co === 'number') parts.push(gasTxt('CO', g.co, g.coTime));
    if (r.other) parts.push(r.other);
    if (!parts.length) return null;
    return (forSpeech ? 'Last air test: ' : '') + parts.join(', ') + (probs.length ? (forSpeech ? ' \u2014 outside safe limits' : ' \u2014 OUTSIDE ACCEPTABLE RANGE') : '') + (forSpeech ? '.' : ' (at ' + new Date(r.time).toLocaleTimeString() + ')');
