    if (k.obs.unsafe && pbObsSupersedes(k.obs, confinedLastObservation)) confinedLastObservation = { ...k.obs, time: new Date(k.obs.time) };
    pbRefreshLatchGases([k.obs]); // also keeps it on the permit when it is in no log
