    if (cn) cn.style.display = restored ? 'none' : '';
    { const xn = document.getElementById('cpEmergencyClosedNote'); if (xn) xn.style.display = 'none'; } // a live permit's panel, not a closed one's
    if (rn) rn.style.display = restored ? '' : 'none';
