    const nr = Array.isArray(entry.permit.numbersReached) ? entry.permit.numbersReached : [];
    const open = (Array.isArray(entry.permit.emergencyIncidents) ? entry.permit.emergencyIncidents : []).filter(i => i && i.start && !i.end).pop();
