    if (typed && !(nr.length && nr[nr.length - 1] && nr[nr.length - 1].number === typed)) head.push('NUMBER IN THE EMERGENCY PANEL BOX (filled in with the number dialed unless changed by hand; the app cannot know whether a call connected): ' + typed);
    const subject = 'EMERGENCY \u2014 Confined Space Entry \u2014 ' + (entry.space || '') + ' \u2014 ' + (entry.address || '');
    pbNavigateExternal('mailto:' + encodeURIComponent(email) + '?subject=' + encodeURIComponent(subject) + '&body=' + encodeURIComponent(head.join('\n') + '\n\n' + entry.reportText));
