    // Still due? Not once the permit closed, an emergency opened, or (for comm) nobody is inside.
    const due = pbReminderQueue.filter(r => confinedPermit && !pbEmergencyOpen() && (r.kind !== 'comm' || confinedRoster.some(x => x.status === 'in')));
    pbReminderQueue = [];
