    const fireAtmoAlert = () => {
      pbPlayAlarm('atmo');
      pbShowReminder('atmo', 'Time to log a fresh air quality reading in the Atmospheric Test Log.', 'Air Test Due');
      return confinedRoster.some(r => r.status === 'in') ? Math.min(PB_OVERDUE_REPEAT_MS, ms) : ms;
    };
    const runAtmo = () => { confinedAtmoTimer = setTimeout(runAtmo, fireAtmoAlert()); };
    const firstDelay = confinedAtmoNextDue.getTime() - Date.now();
