    { const un = pbUnloggedHazards(confinedPermit, confinedAtmoLog.concat(pendAtmo)); // a pending one is listed above
      if (un.length) { lines.push('\u26a0 HAZARDOUS AIR TESTS NOT IN THE LOG ABOVE (' + un.length + ') \u2014 refused (e.g. no tester name) or not saved; each sounded EVACUATE:'); un.forEach(h => lines.push('   ' + pbUnloggedHazardLine(h, confinedPermit))); } }
