    const s = document.querySelector('#toolsList section[aria-label="' + String(name).replace(/"/g, '') + '"]'); if (!s) return;
    const h = document.querySelector('#screen-calcHub .pb-header'), hh = h ? h.getBoundingClientRect().height : 0;
