      + '<section class="pb-edu-block pb-tools-solo" aria-label="Home shortcuts"><div class="pb-tools-group">' /* feat_core33 K7: no heading over one row */
      + '<button type="button" class="pb-edu-row pb-tool-row" id="toolsEditShortcuts" data-ic="star" onclick="pbOpenShortcutsEdit()"><span class="pb-tool-ic" aria-hidden="true"></span><span class="tx"><span class="name">Edit Home shortcuts</span><span class="sub">Pick the tools shown on Home</span></span><span class="chev" aria-hidden="true">&rsaquo;</span></button>'
