    if (!box || !res) return;
    const q = box.value.trim();
    if (!q) { res.style.display = 'none'; res.innerHTML = ''; if (list) list.style.display = ''; if (cats) cats.style.display = ''; return; }
    const hits = pbDestSearch(q, c.dests());
