  window.pbToolsSearch = function() { pbToolsSearchIn({ box: 'toolsSearchBox', res: 'toolsSearchResults', list: 'toolsList', cats: 'toolsBrowseCats', dests: pbToolsDests, one: 'calculator', many: 'calculators', suggest: PB_TOOLS_SUGGEST }); };
  window.pbToolsAllSearch = function() { pbToolsSearchIn({ box: 'toolsAllSearchBox', res: 'toolsAllResults', list: 'toolsAllList', dests: pbToolsAllDests, one: 'tool', many: 'tools', suggest: PB_TOOLS_ALL_SUGGEST }); };
