  // ---------- My Shortcuts: per-account state ----------
  // set: false = never chosen (the D5 defaults show); set: true with ids [] = the person chose none.
  let pbSc = { loaded: false, uid: null, set: false, ids: [] };
  let pbScShowAll = false, pbScLoadGen = 0;
  function pbScParse(raw) {
    if (raw == null) return { set: false, ids: [] };
    try {
      const o = JSON.parse(raw);
      if (o && o.v === 1 && Array.isArray(o.ids)) return { set: true, ids: [...new Set(o.ids.filter(x => typeof x === 'string' && x))] };
    } catch (e) { /* unreadable: the defaults show; nothing is overwritten until the person saves */ }
    return { set: false, ids: [], unreadable: true };
  }
  async function pbScLoad(uid) {
    const gen = ++pbScLoadGen;
    const raw = await pbGetFor(uid, 'homeShortcuts');
    if (gen !== pbScLoadGen) return;
    pbSc = Object.assign({ loaded: true, uid }, pbScParse(raw));
    pbScShowAll = false;
    if (pbCurrentScreen === 'shortcutsEdit') pbScDraftReset(); // another account's list is never edited on top of this one's
    pbRenderShortcuts(); pbScSyncAddButtons();
  }
  async function pbScEnsureLoaded() { if (!pbSc.loaded) await pbScLoad(await pbResolveStorageUserId()); }
  const pbScIds = () => pbSc.set ? pbSc.ids.slice() : PB_SC_DEFAULTS.slice();
  async function pbScSave(ids) {
    const uid = pbSc.uid || await pbResolveStorageUserId();
    const clean = [...new Set(ids)];
    const ok = await pbSetFor(uid, 'homeShortcuts', JSON.stringify({ v: 1, ids: clean, setAt: Date.now() }));
    if (ok && uid === pbSc.uid) { pbSc.set = true; pbSc.ids = clean; }
    pbRenderShortcuts(); pbScSyncAddButtons();
    return ok;
  }
  window.pbAccountLoadHooks = Array.isArray(window.pbAccountLoadHooks) ? window.pbAccountLoadHooks : [];
