  // ---------- My Shortcuts: the editor ----------
  let pbScDraft = [], pbScDirty = false;
  function pbScDraftReset() { pbScDraft = pbScIds(); pbScDirty = false; const s = document.getElementById('scEditSearch'); if (s) s.value = ''; const m = document.getElementById('scEditMsg'); if (m) m.style.display = 'none'; pbShortcutsEditRender(); }
