    return html.replace(/\u0000/g, '<mark>').replace(/\u0001/g, '</mark>').replace(/<mark>([^<]*)<mark>/g, '<mark>$1').replace(/<\/mark>([^<]*)<\/mark>/g, '$1</mark>');
