      const msg = 'This saved reference was retired: ' + (r.retired.note || 'it is no longer in the app.') + (rep && !rep.missing && !rep.retired ? ' The reviewed replacement is “' + rep.title + '”.' : '');
      if (rep && !rep.missing && !rep.retired) pbConfirm(msg, () => pbEduOpenRef(r.retired.replacedBy), 'Reference Replaced');
      else pbAlert(msg, 'Reference Retired');
