      const screen = pbEduArticleEl(id); if (!screen) return;
      const a = PB_EDU_ARTICLES[id];
      const header = screen.querySelector('.pb-header');
      const bar = document.createElement('div');
      bar.className = 'pb-edu-bar pb-edu-ui';
      bar.innerHTML = '<button type="button" class="pb-edu-save" data-edu-save="' + id + '" aria-pressed="false" onclick="pbEduToggleSave(\'' + id + '\')">☆ Save Reference</button>'
        + (a.review ? '<button type="button" class="pb-chip ok pb-edu-srcchip" aria-controls="eduSrc_' + id + '" onclick="pbEduShowSources(\'' + id + '\')">Source check by Claude · ' + escapeHtml(a.review.date) + '</button>' : '<button type="button" class="pb-chip draft pb-edu-srcchip" aria-controls="eduSrc_' + id + '" onclick="pbEduShowSources(\'' + id + '\')">Awaiting source review</button>')
