      { h: 'The same stake with a fill', lines: ['F 0.75 instead of C 4.60', 'Grade = 103.00 ft + 0.75 ft = <strong>103.75 ft</strong>'] },
      { h: 'Station to feet', lines: ['2+50 = 2 × 100 + 50', '<strong>250.00 ft</strong> along the line from 0+00'] },
      { h: 'Engineer’s rod reading at grade', lines: ['Rod on the hub reads 3.10 ft; cut 4.60 ft', 'Reading at the invert = 3.10 + 4.60 = <strong>7.70 ft</strong>'] }
