        { key: 'd', label: 'Horizontal distance, start to end', name: 'the distance', unit: 'ft', ex: '100.00', stepC: 1000, words: ['Shorter 10 ft', 'Longer 10 ft'], names: ['Make the distance 10 ft shorter', 'Make the distance 10 ft longer'], range: () => ({ min: 100, max: 100000 }) }
