    const existingVal = jobsiteFilter.value;
    const jobsites = dedupeCaseInsensitive(runArchive.map(e => e.jobsite).filter(j => j));
    jobsiteFilter.innerHTML = '<option value="all">All Jobsites</option>' + jobsites.map(j => `<option value="${escapeHtml(j)}">${escapeHtml(j)}</option>`).join('');
    jobsiteFilter.value = jobsites.includes(existingVal) ? existingVal : 'all';
