      // meanwhile, its session would carry them — stop instead of filing this
      // report's photos under that account.
      const ownerId = sbUser.id;
      const sameOwner = () => !!sbUser && sbUser.id === ownerId;
      // The login service's session must be this account's own (another tab may have signed in): owed otherwise.
      if (!(await pbLiveSessionIs(ownerId)) || !sameOwner()) { await oweUpload(); return; }
      const pbLegacyRep = ({
        category: entry.category,
        description: entry.description,
        anonymous: entry.anonymous,
        reporter_name: entry.anonymous ? null : (entry.reporterName || null),
        recipient_email: entry.recipientEmail,
        sent: false
      });
      const { data, error } = await pbLegacyWrite('pb_legacy_report_put', { p_report: pbLegacyRep, p_expect_uid: ownerId }, 30000,
        () => sbClient.from('management_reports').insert(pbLegacyRep).select().single()); /* feat_security S3 */
      if (error) { console.error('Supabase insert (management_reports) failed:', error.message); await oweUpload(); return; }
      entry.managementReportSupabaseId = data.id;
