  let pbReportSendingGen = -1; // the form whose submission is in flight
  function pbDiscardReportDraft() { pbReportFormGen++; }
  // Comma-separated addresses are allowed (mail apps accept them); each one
  // must look like name@domain.tld.
  function pbReportEmailOk(v) {
    const parts = v.split(',').map(x => x.trim());
    return parts.length > 0 && parts.every(x => /^[^\s@,;<>()\[\]"]+@[A-Za-z0-9](?:[A-Za-z0-9-]*[A-Za-z0-9])?(?:\.[A-Za-z0-9](?:[A-Za-z0-9-]*[A-Za-z0-9])?)+$/.test(x));
  }
  // saveOnly (Save Without Sending): nobody to send it to, so it is kept in the
