  window.pbSendManagementReport = async function(saveOnly) {
    const errEl = document.getElementById('riError');
    const formGen = pbReportFormGen;
    if (pbReportSendingGen === formGen) { errEl.textContent = 'This report is already being sent \u2014 wait for it to finish.'; errEl.style.display = ''; return; }
    pbReportSendingGen = formGen;
    const release = () => { if (pbReportSendingGen === formGen) pbReportSendingGen = -1; };
    let awaitingAnswer = false;
    try { awaitingAnswer = await pbSendManagementReportOnce(formGen, release, undefined, saveOnly === true); }
    finally { if (!awaitingAnswer) release(); }
  };
  // Batch 4 (R3): Management report goes THROUGH THE APP (owner: no email). The report is saved on this
