    const reportMode = activeVal('riAnonToggle');
    const reportPhotoIds = () => ((window._pbPhotos && window._pbPhotos['riPhoto']) || []).map(p => p.captureId);
    const startPhotoIds = reportPhotoIds();
    const startPending = [...pbPendingCaptures].filter(r => r.prefix === 'riPhoto').length;
    const reportAbandoned = () => pbReportFormGen !== formGen || window._pbPhotoContextGen !== reportPhotoGen;
    const reportUid = await pbResolveStorageUserId(); // the account this report is written under, fixed before any wait
    const category = document.getElementById('riCategory').value;
    const description = document.getElementById('riDescription').value.trim();
    const isAnon = activeVal('riAnonToggle') === 'anon';
