    if (!description) { errEl.textContent = 'Enter a description of what you’re reporting.'; errEl.style.display = ''; return; }
    if (isAnon && !pbReportCanMakeToken()) { errEl.textContent = 'This phone’s browser can’t make the secret reply key an anonymous report needs, so nothing was saved. Update the browser, or send it with your name.'; errEl.style.display = ''; return; }
    errEl.style.display = 'none';
