        r = await pbReportAnonCall('pb_report_submit_anonymous', { p_company_id: a.companyId, p_report_key: a.key, p_client_report_id: e.clientReportId, p_category: e.category, p_body: e.description, p_reply_token: e.replyToken, p_photo_count: e.photoCount || 0 });
