      let r;
      if (e.anonymous) { r = await pbReportAnonCall('pb_report_add_photo_anonymous', { p_reply_token: e.replyToken, p_client_report_id: e.clientReportId, p_seq: i, p_data_b64: b64 }); if (r.deferred) return 'deferred'; }
