        const w = e.deliveryWhy;
        const tail = w === 'privacy' ? 'For your privacy, an anonymous report goes out on its own a few minutes after the app\u2019s other traffic \u2014 usually within 15 minutes while the app is open (or after you next open it).'
          : w === 'key' ? 'Your company\u2019s report key changed; this phone gets the new one the next time it checks, and the report goes after that.'
          : w === 'offline' ? 'This phone has no connection right now; it goes by itself when there’s signal.'
          : w === 'signin' ? 'Sign in to this account with signal and it goes by itself.'
          : w === 'busy' ? 'The server is busy; it tries again by itself in a few minutes.'
          : w ? 'The server couldn’t be reached; it tries again by itself.' : 'Sending…';
