    if (PB_PHOTO_FINAL.includes(e.photosWhy)) return { cls: 'pb-rr-bad', chip: 'Sent \u00b7 ' + ph + ' need' + (left > 1 ? '' : 's') + ' attention', words: s.words + ' But ' + ph + (left > 1 ? ' have' : ' has') + ' not arrived. Photos: ' + pbReportPhotoWords(e), bad: true };
