      if (!sbUser || sbUser.id !== uid) return 'stop';
      if (!(await pbLiveSessionIs(uid))) { await pbSupPatch(uid, it.cid, { why: 'wrong_account', whyAt: Date.now() }); return 'stop'; }
      const r = await pbReportRpc('pb_feedback_send', { p_client_message_id: it.cid, p_kind: it.kind === 'idea' ? 'idea' : 'problem', p_body: it.body, p_app_build: it.build, p_screen: it.screen, p_expect_uid: uid, p_phone: it.phone || null }); /* r16.69: phone */ /* r16.66: problem or idea */
