    if (row) row.hidden = !L.reader && !L.also.includes('material_alert'); // r14 integration: before the paste a PM's material alerts are filed under this kind
    { const sub = row ? row.querySelector('.sub') : null; if (sub) sub.textContent = L.also.includes('material_alert') ? (L.reader ? 'Company account only. Also material alerts, until they get their own switch' : 'Material alerts for your jobs, until they get their own switch') : 'Company account only'; }
    Object.keys(PB_PUSH_ROWS).forEach(k => { const r = document.getElementById(PB_PUSH_ROWS[k]), inp = r ? r.querySelector('input') : null; if (r) r.hidden = !L.kinds.includes(k) || (k === 'delays' && !(typeof window.pbIsCompanyHome === 'function' && window.pbIsCompanyHome(pbArchiveOwnerUid))) /* feat_dailyplus */ || (k === 'safety' && !pbDlyAcc(pbArchiveOwnerUid).manager) || (k === 'permit_closed' && !(typeof window.pbLvIsForeman === 'function' && window.pbLvIsForeman(pbArchiveOwnerUid))) || (k === 'schedule' && !pbCxDashOn()); /* feat_schedule: company accounts */ if (inp) inp.checked = L.prefs[k]; });
