  let pbPushStartLink = null;
  try { if (/^#\/[a-z0-9/_-]{1,60}$/.test(window.location.hash || '')) { pbPushStartLink = window.location.hash; history.replaceState(history.state, '', window.location.pathname + window.location.search); } } catch (e) {}
  window.pbAccountLoadHooks.push(() => { if (pbPushStartLink) { const h = pbPushStartLink; pbPushStartLink = null; setTimeout(() => window.pbPushOpen(h), 600); } });
