    const permits = runArchive.filter(e => e && e.kind === 'confined');
    let canPermits = false; try { canPermits = pbScreenAccessAllowed('confinedHub'); } catch (x) {}
    if (!sbUser || (!permits.length && !canPermits)) { box.hidden = true; box.innerHTML = ''; return; }
    const states = permits.map(pbPermitBkStateOf), count = (k) => states.filter(s => s.k === k).length;
    const ok = count('ok'), refused = count('refused'), failing = count('failing'), unknown = count('unknown'), quota = count('quota'), N = permits.length;
    let line;
