    const i = runArchive.findIndex(x => x && x.id === id), pre = i === -1 ? null : document.getElementById('archiveView' + i);
    if (!pre) return;
    const row = pre.closest('.pb-arch-row');
    if (row) { row.classList.add('pb-fx-focus'); const det = row.querySelector('details.pb-arch-moreacts'); if (det) det.open = true; }
    try { pre.scrollIntoView({ block: 'center' }); } catch (e) {}
