    if (document.getElementById('jobsAddForm')) pbJobsShowAdd(false);
    let list = [], failed = false;
    try {
      const raw = await pbGetCriticalFor(uid, 'jobsList');
      if (raw !== null && raw !== undefined) {
        const v = JSON.parse(raw);
        if (!v || typeof v !== 'object' || !Array.isArray(v.jobs)) throw new SyntaxError('not a job list');
        list = v.jobs.filter(pbJobsValidAdded).map(a => ({ number: String(a.number || '').trim(), site: String(a.site || '').trim(), addedAt: typeof a.addedAt === 'number' ? a.addedAt : 0 }));
      }
    } catch (e) { failed = true; console.error('Jobs list could not be read:', e); }
    if (gen !== pbJobsLoadGen) return; // a later load (another account) took over
