  // ---------- Save to Phone (UX batch 2, D7) ----------
  // A plan without Records (the individual plan) gets a file of the open run's results: the same
  // run record Records's PDF uses (plain text when the PDF maker didn't load). The file is handed
  // to the phone's share sheet or downloaded; nothing is stored in the app.
  function pbUpdateSaveToPhone() {
    const wrap = document.getElementById('saveToPhoneWrap'); if (!wrap) return;
    const e = getCurrentArchiveEntry();
    wrap.style.display = (e && e.kind === 'run' && !pbCanOpen('archive')) ? '' : 'none';
    const m = document.getElementById('saveToPhoneMsg'); if (m) { m.style.display = 'none'; m.textContent = ''; }
  }
  async function pbHandFileToPhone(blob, name) {
    try {
      const file = new File([blob], name, { type: blob.type });
      if (navigator.share && navigator.canShare && navigator.canShare({ files: [file] })) {
        try { await navigator.share({ files: [file], title: name }); return 'shared'; }
        catch (e) { if (e && e.name === 'AbortError') return 'cancelled'; } // anything else: download instead
      }
    } catch (e) {}
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url; a.download = name; a.style.display = 'none';
    document.body.appendChild(a); a.click(); a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 60000);
    return 'downloaded';
  }
  // entryId: the run to save (the Home offer passes it); none = the run open on Results.
  window.pbSaveRunToPhone = async function(entryId) {
    const fromHome = entryId !== undefined && entryId !== null;
    const entry = fromHome ? runArchive.find(e => e && e.kind === 'run' && e.id === entryId) : getCurrentArchiveEntry();
    const msg = document.getElementById(fromHome ? 'homeSaveOfferMsg' : 'saveToPhoneMsg');
    if (!entry || entry.kind !== 'run') { pbAlert('This run isn’t on this phone any more. No file was made.', 'Run Not Found'); if (fromHome) pbRenderSaveOffer(); return; }
    const btn = document.getElementById(fromHome ? 'homeSaveOfferBtn' : 'saveToPhoneBtn');
    const safe = s => String(s || '').replace(/[^a-z0-9]+/gi, '-').replace(/^-+|-+$/g, '').slice(0, 40) || 'point';
    const lt = entry.lockTime instanceof Date ? entry.lockTime : new Date(entry.lockTime);
    const pad = n => String(n).padStart(2, '0');
    const day = isFinite(lt.getTime()) ? lt.getFullYear() + '-' + pad(lt.getMonth() + 1) + '-' + pad(lt.getDate()) : 'run';
    const base = 'run-results-' + safe(entry.startLabel) + '-to-' + safe(entry.endLabel) + '-' + day;
    if (btn) { btn.disabled = true; btn.textContent = 'Making File…'; }
    if (msg) msg.style.display = 'none';
    try {
      let blob, name, asText = false;
      if (pdfLibReady()) {
        const unreadable = await pbPreflightPdfImages([entry]);
        const doc = pbNewPdf(); doc.__pbUnreadable = unreadable;
        addEntryToPDF(doc, entry, 20);
        blob = doc.output('blob'); name = base + '.pdf';
      } else {
        blob = new Blob([buildRunReportFromEntry(entry)], { type: 'text/plain' }); name = base + '.txt'; asText = true;
      }
      const how = await pbHandFileToPhone(blob, name);
      if (how === 'cancelled') return;
      const text = (how === 'shared' ? 'File sent to your phone’s share menu: ' : 'File downloaded: ') + name + '. Check your Downloads or Files to make sure it saved.' + (asText ? ' The PDF maker didn’t load, so this is a plain text file.' : '');
      if (!fromHome && msg) { msg.textContent = text; msg.style.display = ''; }
      if (pbSaveOffer && pbSaveOffer.entryId === entry.id) { if (fromHome) pbSaveOfferNote = text; pbClearSaveOffer(); } // saved: the Home offer for it is done
    } catch (e) {
      console.error('Save to Phone failed:', e);
      pbAlert('The file couldn’t be made. The run is unchanged. Try again.', 'Not Saved to Phone');
    } finally {
      const b2 = document.getElementById(fromHome ? 'homeSaveOfferBtn' : 'saveToPhoneBtn');
      if (b2) { b2.disabled = false; b2.textContent = 'Save to Phone'; }
    }
  };
  // ---------- Save to Phone offer on Home (UX batch 2, D7) ----------
  // After End Run / End Run Incomplete saves, an individual-plan user (no Records) gets one line on Home:
  // "Run ended — Save it to your phone", with Save to Phone and Dismiss. Not a work card (D6): it sits
  // outside Current Work, just before the Needs Attention marker, and is not a .pb-home-tile.
  // Stored per account as {v:1, entryId, at} under 'saveToPhoneOffer' (the id only, never the run).
  // Gone after a save, Dismiss, a newer run locked, or the run removed; another account has its own.
  // The plan is checked each time the line is drawn, not only when the run ended.
  let pbSaveOffer = null;      // { uid, entryId }: its owner account and run, or null
  let pbSaveOfferUid = null;   // the account whose offer is loaded (null while loading)
  let pbSaveOfferNote = '';    // what the last save from the offer did, shown until Home is left
  let pbSaveOfferGen = 0;
  function pbSaveOfferAllowed() { return !pbCanOpen('archive') && pbCanOpen('jobs'); }
