    if (el) return el;
    const home = document.getElementById('screen-home'); if (!home) return null;
    el = document.createElement('div');
    el.id = 'homeSaveOffer'; el.className = 'pb-save-offer'; el.style.display = 'none';
    // Placed at runtime, just before the Needs Attention marker, so no other area's markup is edited.
