    if ((e.roster || []).length) R.table({ head: ['Name (typed)', 'Role', 'Check-ins and check-outs (device time)', 'At closeout'], body: pbRptRosterBody(e), columns: [{ cellWidth: 38 }, { cellWidth: 30 }, {}, { cellWidth: 22 }] });
