  // ----- EMERGENCY incident report: a separate record of each emergency declared on a permit -----
  window.pbDownloadEmergencyPDF = async function(i) {
    if (!pdfLibReady()) { pbAlert('PDF library didn\'t load \u2014 check your connection and try again.'); return; }
    const entry = runArchive[i];
    if (!pbRptHasEmergency(entry)) { pbAlert('No emergency was declared on this permit, so there is no incident report.', 'No Emergency'); return; }
    const n = pbRptPhotoTotal([entry]);
    if (n > 6) await pbRptBusy('Making the PDF: preparing ' + n + ' photos\u2026');
    let doc;
    try {
      const unreadable = await pbPreflightPdfImages([entry], (d, t) => { if (t > 6) pbRptBusy('Making the PDF: photo ' + d + ' of ' + t + '\u2026'); });
      const meta = { title: 'EMERGENCY Incident Report', creator: pbRptBuild() };
      try { doc = pbRptMake((R) => pbRptEmergencyInto(R, entry), { unreadable, meta }); }
      catch (err) { console.error('PDF: incident report laid out as data only:', err); doc = pbRptMake((R) => pbRptFallbackInto(R, entry, String(err && err.message || err)), { unreadable, meta }); }
    } finally { pbRptBusy(null); }
    doc.save('emergency-incident-' + entry.id + '.pdf');
  };
