      ['EMERGENCY button number', (p.emergencyDialNumber || 'not recorded') + ' (the number the EMERGENCY button opens the dialer with)'], ['Call button', dials.length ? dials.map(d => pbRptDialWords(d)).join(' ') : 'No tap of the EMERGENCY button is recorded.'], pbRptTexts(p).length ? ['Texts', pbRptTexts(p).map(x => pbRptTextWords(x)).join(' ')] : null, pbRptFixes(p).length ? ['Position at EMERGENCY', pbRptFixes(p).map(f => pbRptFixWords(f)).join(' ')] : null,
      ['Numbers recorded', reached.length ? reached.map(n => pbRptNumberWords(n, false, p)).join(' ') : 'none recorded'], ['Delivery', PB_RPT_NOTIFY_UNKNOWN], ['Entry supervisor / attendant', (p.supervisor || '\u2014') + ' / ' + (p.attendant || '\u2014')]
