      (p.dialNumberLog || []).filter(c => c.time >= t0 && incOf(c.time) === i).forEach(c => acts.push([c.time, 'The number the EMERGENCY button opens the dialer with was changed from ' + c.from + ' to ' + c.to]));
      (e.roster || []).forEach(person => (person.log || []).forEach(l => { const t = pbRptMs(l.time); if (t >= t0 && t <= t1) acts.push([t, person.name + ' (' + person.role + '): ' + String(l.action || '').toLowerCase() + pbAgainstBlockText(l)]); }));
      air.filter(r => pbRptMs(r.time) >= t0 && pbRptMs(r.time) <= t1).forEach(r => acts.push([r.time, 'Air test: O2 ' + r.o2 + '%, LEL ' + r.lel + '%' + (typeof r.h2s === 'number' ? ', H2S ' + r.h2s + ' ppm' : '') + (typeof r.co === 'number' ? ', CO ' + r.co + ' ppm' : '') + ' (tester ' + r.tester + ')']));
      if (inc.end) acts.push([inc.end, pbRptIncOutcome(inc) + (inc.outcomeNote ? ' \u2014 note: "' + inc.outcomeNote + '"' : '')]);
