      R.para(PB_RPT_NOTIFY_UNKNOWN, { size: 9, style: 'bold' });
      R.table({ head: ['Device time', 'Elapsed', 'Action'], body: acts.map(a => [pbRptDt(a[0], { sec: true }), '+' + pbRptDur((pbRptMs(a[0]) - t0) / 1000), a[1]]), columns: [{ cellWidth: 48 }, { cellWidth: 20, halign: 'right' }, {}] });
      const inside = pbRptInsideAt(e, t0);
      R.sub('Who was inside when it was declared (from the roster log)');
      R.table({ head: ['Name (typed)', 'Role', 'Checked in', 'Next check-out'], body: inside.length ? inside.map(x => { const out = (x.person.log || []).find(l => /^Checked out/i.test(l.action) && pbRptMs(l.time) > t0); return [x.person.name, x.person.role, pbRptDt(x.since, { sec: true }), out ? pbRptDt(out.time, { sec: true }) + ' (+' + pbRptDur((pbRptMs(out.time) - t0) / 1000) + ')' : { content: 'no check-out logged', _accent: true }]; }) : [[{ content: 'No one was checked in at that moment (by the roster log).', colSpan: 4 }]], columns: [{ cellWidth: 40 }, { cellWidth: 30 }, { cellWidth: 44 }, {}] });
      const before = air.filter(r => pbRptMs(r.time) < t0).slice(-2), during = air.filter(r => pbRptMs(r.time) >= t0 && pbRptMs(r.time) <= t1), after = air.filter(r => pbRptMs(r.time) > t1).slice(0, 2);
      R.sub('Air readings before, during and after');
      const ab = [];
      before.forEach(r => ab.push([{ content: 'Before', _bold: true }].concat(pbRptAirRow(e, r))));
      during.forEach(r => ab.push([{ content: 'During', _accent: true }].concat(pbRptAirRow(e, r))));
      after.forEach(r => ab.push([{ content: 'After', _bold: true }].concat(pbRptAirRow(e, r))));
