    reached.forEach(n => { const k = pbRptNumberKind(n, p); nrows.push([pbRptNumberLabel(n, p), pbRptDt(n.time, { sec: true }), k === 'app' ? 'Recorded when Send Report Email was tapped. The app filled in this number after EMERGENCY and nobody changed it. Whether an email was opened or sent is not recorded.' : k === 'same' ? 'The \u201cEmergency number called\u201d box was edited by hand on this phone; the number is the one the app filled in.' : 'Typed in the \u201cEmergency number called\u201d box on this phone.', { content: 'Shows what was recorded, not that anyone answered', _accent: true }]); });
