      ['Delivery', st ? st.words : (e.sent ? 'Emailed (older report)' : 'Not sent')], ['Last delivery update', e.deliveryAt ? pbRptDt(e.deliveryAt, { sec: true }) + ' (device time; server-received time is kept on the server)' : null],
      ['Photos', n + (e.via === 'app' ? ' (' + Math.min(sent, n) + ' sent)' : '')], ['Sent through', e.via === 'app' ? 'the app (to the company\u2019s Management inbox)' : 'email (older report)']
