    R.section('runs', 'Runs included (' + entries.length + ')', { keep: 30, intro: 'One row per tracked run, oldest first. Footage to one decimal, as in the run record and the Job Summary.' });
    const runLabel = (id) => { const a = runArchive.find(x => x && x.kind === 'run' && x.id === id); return a ? (a.startLabel || '') + ' to ' + (a.endLabel || '') + (a.incomplete ? ' (ended early)' : '') : 'run not on this phone'; };
    const sorted = entries.slice().sort((a, b) => pbRptMs(a.date) - pbRptMs(b.date));
    const size = (e) => (e.sizeSegments && e.sizeSegments.length > 1) ? e.sizeSegments.map(s => (s.sizeIn > 0 ? s.sizeIn.toFixed(1) + '"' : '?') + ' ' + s.footage.toFixed(1)).join(' + ') : (typeof e.sizeIn === 'number' && e.sizeIn > 0 ? e.sizeIn.toFixed(1) + '"' : 'not recorded');
    R.table({ head: ['Locked', 'Run', 'Job', 'Pipe type', 'Size', 'Footage', 'Elapsed', 'Pipelayer'], body: sorted.map(e => [pbRptDt(e.date, { noTz: true }), runLabel(e.entryId), e.jobNumber || '\u2014', e.type, size(e), e.footage.toFixed(1) + ' ft', typeof e.durationMin === 'number' && e.durationMin > 0 ? fmtDuration(e.durationMin) : '\u2014', e.pipelayer || '\u2014']), foot: ['Total', '', '', '', '', total.toFixed(1) + ' ft', '', ''], columns: [{ cellWidth: 30 }, { cellWidth: 32 }, { cellWidth: 18 }, { cellWidth: 22 }, { cellWidth: 20 }, { halign: 'right', cellWidth: 20 }, { halign: 'right', cellWidth: 17 }, {}], fontSize: 8.8 });
    pbRptIntegrity(R, { kind: 'stats' }, fp, [], 'How the fingerprint is made: SHA-256 of the Stats log entries included above (every field the app keeps for them), written in PostgreSQL\u2019s jsonb text form. The same entries with the same filters give the same fingerprint.');
