    pbRptTitle(R, 'Job Summary: #' + s.jobNumber, (s.jobsites.join(', ') || 'Jobsite not recorded') + ' \u00b7 ' + pbRptDt(s.firstDate, { date: true }) + ' to ' + pbRptDt(s.lastDate, { date: true }));
