    const spacing = sorted.length ? sorted[Math.floor((sorted.length - 1) / 2)] : 0;
    const n = gaps.findIndex((g, k) => g > 50 && g > 2 * spacing && isStructure(byStation[k]) && isStructure(byStation[k + 1]) && ((endStructure(byStation[k]) && endStructure(byStation[k + 1])) || (k > 0 && k + 2 < byStation.length)));
    const at = n === -1 ? k2 : k2 === -1 ? n : Math.min(n, k2);
