      document.getElementById(prefix + 'CutFill').value = row.cfType || 'cut';
      setElevFieldValue(prefix + 'CutFillVal', row.cfVal !== null ? row.cfVal : 0, arch);
      const labelEl = document.getElementById(prefix + 'Label');
      const also = row._alsoNote ? ' \u2014 ' + row._alsoNote.text : ''; // a lateral noted on this structure (set by the validation just run)
      if (labelEl) labelEl.value = row.description + ' (stake ' + row.stakeNum + (along ? ', sta ' + pbCutsheetStaText(row.station) : '') + ')' + also; // both ways: the sheet station stays beside the distance
