    { const ok = document.querySelector('#pbModalButtons button'); if (ok) ok.addEventListener('click', () => setTimeout(() => { try { const wt = document.getElementById('runWT'); if (wt && String(wt.value || '').trim() === '' && pbCurrentScreen === 'input') pbGoToField('runWT'); } catch (e) {} }, 60), { once: true }); } /* cleanup A (P2): filled (auto or remembered): no scroll */
