    if (!arch) { const s = document.getElementById('qrReadingStart'), e = document.getElementById('qrReadingEnd'); if (s) s.closest('.pb-field').querySelector('label').htmlFor = 'qrReadingStart'; if (e) e.closest('.pb-field').querySelector('label').htmlFor = 'qrReadingEnd'; }
