  function buildStatsSnapshotReportFor(entries) {
    let lines = ['PIPELAYER\'S BIBLE — STATS DATA (CLEARED SNAPSHOT)', 'Generated: ' + new Date().toLocaleString(), ''];
    const totalFootage = entries.reduce((sum, e) => sum + e.footage, 0);
    lines.push('This is a record of Stats data at the moment it was cleared from the app.');
    lines.push('Total footage: ' + totalFootage.toFixed(0) + ' ft across ' + entries.length + ' run(s)');
    lines.push('');
    lines.push('--- INDIVIDUAL ENTRIES ---');
    entries.forEach(e => {
      const sizeTxt = (sz) => (sz !== null && sz !== undefined && sz > 0 ? sz.toFixed(1) + '"' : 'size not recorded');
      // A reducer run is several sizes: list each size's own footage, since this
      // snapshot is the only record left once Stats is cleared.
      const sizeAndFootage = (e.sizeSegments && e.sizeSegments.length > 1)
        ? e.sizeSegments.map(sg => sizeTxt(sg.sizeIn) + ' ' + sg.footage.toFixed(1) + ' ft').join(' + ') + ' = ' + e.footage.toFixed(1) + ' ft'
        : sizeTxt(e.sizeIn) + ' — ' + e.footage.toFixed(1) + ' ft';
      lines.push(e.date.toLocaleString() + ' — ' + e.type + ', ' + sizeAndFootage + (e.jobsite ? ' — ' + e.jobsite : '') + (e.crew ? ' — ' + e.crew : ''));
    });
    return lines.join('\n');
  }
  window.pbClearAllStats = function() {
    if (!statsLog.length) { pbAlert('No Stats data to clear.'); return; }
    pbConfirm('Delete all Stats on this phone? Saved runs stay. A snapshot goes to Records first (Contractor plan).', async () => {
      // Phase 1: capture EXACTLY what will be archived and removed, under
      // the stats lock but released immediately — never held across the
      // archive save below. Holding it there would risk a deadlock if
      // archive reconciliation's own logic ever needs the same stats lock
      // while this is still waiting on saveRunArchive.
      const snapshotEntries = await withStatsLogLock(async () => statsLog); // a reference to the CURRENT array at this exact moment — this, and only this, is what gets archived and later removed
      if (!snapshotEntries.length) { pbAlert('No Stats data to clear.'); return; } // could have changed between the initial button-press check and now
      const totalFootage = snapshotEntries.reduce((sum, e) => sum + e.footage, 0);
      const reportText = buildStatsSnapshotReportFor(snapshotEntries);
      // Phase 2: archive save, entirely outside any stats lock.
      const snapshotRecord = {
        kind: 'stats-snapshot',
        id: Date.now(),
        lockTime: new Date(),
        distance: totalFootage,
        runCount: snapshotEntries.length,
        jobsite: '', jobNumber: '', crew: '',
        photoCount: 0, depthFlagged: false, netCutFill: null, volumeYd3: null,
        reportText: reportText,
        sent: false
      };
      runArchive.unshift(snapshotRecord);
      const archiveSaveOk = await saveRunArchive();
      if (!archiveSaveOk) {
        // The snapshot was not saved: take it back out of memory too, so a later
        // save can't quietly store it (a retry would otherwise leave two).
        const at = runArchive.indexOf(snapshotRecord); if (at !== -1) runArchive.splice(at, 1);
        pbAlert('Snapshot not saved. Stats NOT cleared. Try again.', 'Clear Failed'); return;
      }
      // Phase 3: remove ONLY the specific entries just archived — by
      // reference, against whatever statsLog actually holds NOW, which may
      // have grown or changed since the snapshot was captured. An entry
      // added during the archive save was never part of snapshotEntries, so
      // it's untouched by this filter and survives. An entry that was
      // MODIFIED since the snapshot (this codebase's stats writers replace
      // objects rather than mutating them in place) is, by the same logic,
      // a NEW object no longer matching anything in snapshotEntries — so it
      // also correctly survives, since the archived report describes its
      // OLD content, not whatever it's since become.
      const clearOk = await withStatsLogLock(async () => {
        const priorStatsLog = statsLog;
        statsLog = statsLog.filter(e => !snapshotEntries.includes(e));
        const ok = await saveStatsLog();
        if (!ok) statsLog = priorStatsLog; // restore on failure rather than leaving memory cleared while disk still has the old data
        return ok;
      });
      if (!clearOk) { pbAlert('Snapshot saved, but Stats wasn’t cleared. Try Clear All Stats again.', 'Clear Failed'); return; }
      renderStats();
    }, 'Clear All Stats');
  };

