    await pbMigrateToPerUserStorage(uid);
    if (gen !== pbAuthGen) return;
    await initAutofill();
    if (gen !== pbAuthGen) return;
    await loadActiveConfinedSession();
    if (gen !== pbAuthGen) return;
    await pbLoadCachedSubscription();
    if (gen !== pbAuthGen) return;
    updateLoginStatusDisplay(); // the cached plan, shown now
    pbRefreshPlanInBackground(gen);
    if (lateCheck) pbSettleLateSessionCheck(lateCheck, gen, uid).catch(e => {
      // The records stay as loaded (last verified access); only the late answer is lost.
      console.error('Applying the late session check failed:', e);
      const ov = document.getElementById('pbBootCover'); if (ov && !pbLoginInProgress) ov.style.display = 'none';
    });
