        if (fromEvent) pbAlertAfterOpen('This phone was signed in as ' + (r.session.user.email || 'another account') + ' in another tab or window, so it now shows that account. The records of the account that was open before are kept on this phone \u2014 log in as that account again to see them.', 'Signed In As Another Account');
        else if (viaLink) pbAlertAfterOpen('The email link you opened is for ' + (r.session.user.email || 'another account') + ', so this phone is now signed in as that account. The records of the account that was open before are kept on this phone \u2014 log in as that account again to see them.', 'Signed In From Link');
