    const r = await pbPermitRpc('pb_member_label', { p_user: userId }, 15000);
    if (!sbUser || sbUser.id !== me) return null;
    if (r && r.data && r.data.ok === true) { const v = { name: r.data.name ? pbNameClean(r.data.name) || null : null, email: r.data.email && (String(userId).toLowerCase() === String(me).toLowerCase() || (typeof window.pbAcOffice === 'function' && window.pbAcOffice(me))) ? r.data.email : null }; /* r15.48 access: a coworker's email for the office only */ pbMemberLabelMem.set(k, v); return v; }
    if (r && r.data && r.data.ok === false) { pbMemberLabelMem.delete(k); return null; }
