    const n = (/^seg(\d+)start$/.exec(startPrefix) || [])[1];
    const txt = mode === 'step' ? 'Calculated from the measured step in “Connection to Run ' + n + '”. Type over it to enter the invert yourself.'
      : mode === 'own' ? 'Typed in by you — the measured step above does not change it.' : '';
    tag.innerHTML = txt ? (mode === 'step' ? '<span class="pb-chip calculated">Calculated</span> ' : '<span class="pb-chip">Typed in</span> ') + escapeHtml(txt) : '';
