  window.pbFmRentAdd = function(pre) { const F = pbFmRentF(pre); if (!F || F.rentals.length >= 10) return; F.rentals.push({ name: '', hours: '' }); pbFmRentPaint(pre); setTimeout(() => { const el = document.getElementById(pre + 'RentN' + (F.rentals.length - 1)); if (el) el.focus({ preventScroll: true }); }, 30); };
