      const keep = {}; if (!fresh) grid.querySelectorAll('[data-fm-extra] input').forEach(i => { if (i.value !== i.defaultValue) keep[i.dataset.key] = i.value; });
      grid.querySelectorAll('[data-fm-extra]').forEach(n => n.remove());
