    const e = i >= 0 ? d.events[i] : null;
    pbDp.form = e ? { key: pbDpKey(), i, cid: e.cid, rn: e.rn || null, dn: e.dn || null, dnAt: e.dnAt || null /* proc95, fix95 5 */, kind: e.kind, reason: e.reason, detail: e.detail || '', hours: e.hours === null || e.hours === undefined ? '' : String(e.hours), crew: e.crew_size === null || e.crew_size === undefined ? '' : String(e.crew_size), equipment: (e.equipment || []).map(pbDpEqKey), photos: (e.photos || []).slice(), msg: '' }
      : { key: pbDpKey(), i: -1, cid: pbDlyId(), kind: 'delay', reason: '', detail: '', hours: '', crew: d.crew.length ? String(d.crew.length) : '', equipment: [], photos: [], msg: '' };
