      const b64 = await pbDlyShrink(f); if (!b64) { pbAlert('That photo couldn’t be read.', 'Photo'); continue; }
      let taken = null; try { const m = await pbExifTakenFromFile(f); taken = m && m.taken ? m.taken : null; } catch (e) {}
      let sha = null; try { sha = pbSha256Bytes(Uint8Array.from(atob(b64), ch => ch.charCodeAt(0))); } catch (e) {}
