    const all = [pbMatCoLoad(), window.pbProdDashLoad(), pbBdLoad(true), pbCxInboxLoad(uid, !!force), typeof window.pbRrLoad === 'function' ? window.pbRrLoad(uid, !!force) : null].map(p => Promise.resolve(p).catch(() => null));
