  const PB_RR_DAYS = 21, PB_RR_MAX_PER_PASS = 6;
  let pbRr = { uid: null, sent: null, busy: false, pauseUntil: 0, timer: null, asked: {} };
  function pbRrIsBinary(v) { return typeof v === 'string' && /^data:/.test(v) && v.length > 200; }
  // A deep copy with photo / file data left out: strings in arrays are dropped, objects holding one are dropped from their
