    if (laidFt === null && e.restoredFromCloud && typeof e.restoredLaidFt === 'number') laidFt = e.restoredLaidFt; // r16.15
    const lt = e.lockTime instanceof Date ? e.lockTime : new Date(e.lockTime);
    const wd = isFinite(lt.getTime()) ? lt.getFullYear() + '-' + String(lt.getMonth() + 1).padStart(2, '0') + '-' + String(lt.getDate()).padStart(2, '0') : '';
    rec.pbOffice = { laidFt, photosLeftOut: left, workDate: wd, send: !!(e.reportSendWanted && (e.completed || e.incomplete)) }; // r15.2: Send Report
    if (refs.length && owner && owner !== 'shared') rec.pbOffice.photos = refs.slice(0, 200); /* r16.75: the photos themselves go to run-photos */
