    const X = window.pbCeDailyEq(D).map(x => { if (x.plan_key) return x; const r0 = raw.find(y => y.id === x.id) || {}, co = typeof r0.co_id === 'string' ? r0.co_id : null, q = co ? plan.find(p => p.co_id === co) : null; return Object.assign(x, { co_id: co, rental: r0.rental === true }, q ? { plan_key: q.key } : {}); });
