  // a typed one can be marked rental. ====
  let pbJe = { saving: false, msg: '', job: null, ver: 0, ceAsked: null, mgrAsked: null };
  function pbJePlanEq() { const D = pbPj.data || {}; return (D.plan && Array.isArray(D.plan.equipment) ? D.plan.equipment : []).filter(q => q && typeof q.key === 'string' && /^eq_[a-z0-9]/.test(q.key) && q.key !== 'eq_other'); }
  // who can edit = who can edit the Job plan (the server's managed_company: company account, managers, PMs, supers)
