  function pbJbFormWire() { pbJbPhotosRender(); const b = pbJbEl('jbBody'); if (b && !b._jbWired) { b._jbWired = true; const clr = () => { if (pbJb.form && pbJb.form.err) { pbJb.form.err = ''; const e = pbJbEl('jbFormErr'); if (e) e.textContent = ''; } }; b.addEventListener('input', clr); b.addEventListener('change', clr); } } // a fixed field clears the old message
