      if (f.t === 'num' && x !== '') { const n = Number(String(x).replace(',', '.')); if (!isFinite(n) || n <= 0 || n > 99999) { say(f.l + ': a number of hours above 0.'); return; } v[f.k] = Math.round(n * 100) / 100; }
